# -*- coding: utf-8 -*-
"""М-4 (рядок 156): ЧИ ДОХОДИТЬ СУТЬ ЇЇ БАЖАННЯ ДО ФУНКЦІОНАЛЬНИХ МОДЕЛЕЙ НА ШЛЯХУ ШАРУ. Десять її речень
у внутрішній мові, як їх переклала б сумлінна перекладачка (поле — з дослівною цитатою, сказане поза
полями — `rest`), → шов `мовний_шар.паспорт_з_шару` → те, що моделі справді читають: рука 1 — `case`
пакета дротом (`пакет_моделі.випадок_для_пакета` → `дріт_моделі.випадок`), руки 3–4, ремонт, вибір і
опис — рядок випадку з вимогами (`міст_вхід._застосувати_паспорт`). Друкує, скільки її слів (≥4 літер)
дійшло дослівно; слово, що дійшло лише кодом (`job_interview`), не лічиться. Та сама проба на main і на
гілці — до і після. Запуск із `джерела`: python3 проби/шлях_шар_суть.py"""
import sys, os, re, json
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(sys.path[0])
import мовний_шар as МШ, пакет_моделі as ПМ, дріт_моделі as Д, міст_вхід as МВ
Т = lambda т: {"free_text": т, "lang": "uk"}
РЕЧЕННЯ = [
 ("на концерт у Палаці спорту, там завжди холодно в залі і довго стояти в черзі", dict(event=Т("концерт у Палаці спорту"), place="theatre", setting="indoor", quotes=dict(place="концерт", setting="в залі"), rest=Т("там завжди холодно в залі і довго стояти в черзі"))),
 ("іду на концерт, хочу, щоб подруга впізнала мене здалеку, бо ми ще не бачились", dict(event=Т("концерт"), place="theatre", goal="express", quotes=dict(place="на концерт", goal="щоб подруга впізнала мене здалеку"), rest=Т("бо ми ще не бачились"))),
 ("на співбесіду в банк, хочу, щоб мене сприйняли серйозно, але без чорного костюма", dict(event=Т("співбесіду в банк"), occasion="job_interview", intent="context_optimal", quotes=dict(occasion="на співбесіду", intent="щоб мене сприйняли серйозно"), vetoes=[dict(item_type="suit", color_name="black", quote="без чорного костюма")])),
 ("на весілля до сестри, я свідок, не хочу затьмарити наречену", dict(event=Т("весілля до сестри"), occasion="wedding_guest", goal="conceal", quotes=dict(occasion="на весілля", goal="не хочу затьмарити наречену"), rest=Т("я свідок"))),
 ("на побачення в ресторан, він вищий за мене на дві голови, хочу підбори", dict(event=Т("побачення в ресторан"), occasion="date", quotes=dict(occasion="побачення"), wants=[dict(feature="heels", quote="хочу підбори")], rest=Т("він вищий за мене на дві голови"))),
 ("гуляти з дитиною в парку, весь день на ногах, щоб було зручно і не шкода забруднити", dict(event=Т("гуляти з дитиною в парку"), occasion="walk", place="park", movement="walk_a_lot", intent="comfort_first", quotes=dict(occasion="гуляти", place="в парку", movement="весь день на ногах", intent="щоб було зручно"), rest=Т("не шкода забруднити"))),
 ("на корпоратив на даху, хочу виглядати яскраво, але ввечері там вітер", dict(event=Т("корпоратив на даху"), occasion="celebration", setting="outdoor", goal="express", part_of_day="evening", quotes=dict(occasion="корпоратив", setting="на даху", goal="хочу виглядати яскраво", part_of_day="ввечері"), rest=Т("там вітер"))),
 ("на похорон бабусі, треба щоб було тепло, бо на кладовищі мороз", dict(event=Т("похорон бабусі"), occasion="mourning", setting="outdoor", weather_feel="frost", quotes=dict(occasion="на похорон", setting="на кладовищі", weather_feel="мороз"), rest=Т("треба щоб було тепло"))),
 ("у театр на прем'єру, хочу щось вишукане в пастельних тонах і перли", dict(event=Т("театр на прем'єру"), place="opera_premiere", jewelry="pearls", quotes=dict(place="на прем'єру", jewelry="перли"), wants=[dict(color_class="pastel", quote="в пастельних тонах")], mood=[Т("вишукане")])),
 ("на батьківські збори, не хочу виділятися, люблю класику", dict(event=Т("батьківські збори"), place="school_parents_meeting", goal="conceal", registers=["classic"], quotes=dict(place="на батьківські збори", goal="не хочу виділятися", registers="люблю класику")))]
слова_ = lambda т: set(re.findall(r"[а-яіїєґʼ']{4,}", т.lower().replace("’", "'")))
разом = [0, 0, 0]
for слова, в in РЕЧЕННЯ:
    п = МШ.паспорт_з_шару(в, {}, None, None, слова_ходу=слова)["паспорт"]
    d = МВ._застосувати_паспорт({"паспорт": п, "сценарій": {}})
    рука1 = json.dumps(Д.випадок(ПМ.випадок_для_пакета(п, d["випадок"], d["сценарій"], d["вимоги"])), ensure_ascii=False)
    її, а, б = слова_(слова), слова_(рука1), слова_(d["випадок"] + " " + d["вимоги"])
    разом = [разом[0] + len(її), разом[1] + len(її & а), разом[2] + len(її & б)]
    print("«%s»\n   рука 1: %d/%d, не дійшло: %s\n   руки 3–4: %d/%d, не дійшло: %s" % (слова, len(її & а), len(її),
          ", ".join(sorted(її - а)) or "—", len(її & б), len(її), ", ".join(sorted(її - б)) or "—"))
print("ПІДСУМОК: її слів (≥4 літер) %d; дійшло до руки 1 — %d (%d%%), до рук 3–4 — %d (%d%%)"
      % (разом[0], разом[1], 100 * разом[1] // разом[0], разом[2], 100 * разом[2] // разом[0]))
